 function battleCalculation(attacker,defender,set,move,defenderEvs,master,options={}){const type=$('calcMoveType')?.value.trim()||koreanType[move[2]]||move[2],power=Number($('calcMovePower')?.value)||Number(move[4]),customMove=[...move];customMove[2]=Object.keys(koreanType).find(key=>koreanType[key]===type)||move[2];customMove[4]=power;const calc=engineBattleCalculation(attacker,defender,set,customMove,defenderEvs,master,options);if(!calc)return calc;const factor=advancedBattleMultiplier({category:calc.category,type,status:$('calcStatus').value,ability:set.abilities,manual:Number($('calcManualMultiplier').value),powerSpot:$('calcPowerSpot').checked,flowerGift:$('calcFlowerGift').checked,steelSpirit:$('calcSteelSpirit').checked,fairyAura:$('calcFairyAura').checked,darkAura:$('calcDarkAura').checked,auraBreak:$('calcAuraBreak').checked,tabletsOfRuin:$('calcTablets').checked,swordOfRuin:$('calcSword').checked,vesselOfRuin:$('calcVessel').checked,beadsOfRuin:$('calcBeads').checked,friendGuard:$('calcFriendGuard').checked,doubleSpread:$('calcDouble').value==='더블 배틀'});if(!factor)return null;calc.damage=damageRolls(power,calc.attack*factor.attack,calc.defense*factor.defense,calc.modifier*factor.final).map(value=>value*calc.hits);calc.singleHitDamage=calc.damage.map(value=>Math.floor(value/calc.hits));calc.result=classifyKO(calc.damage,calc.currentHp);calc.advancedMultiplier=factor;return calc}
