 function engineBattleCalculation(attacker,defender,set,move,defenderEvs,master,options={}){const replace=(pokemon,evs,side)=>{const record=master.pokemon.find(row=>row[0]===pokemon.name),ivs=ev(`calc${side}Ivs`),level=Number($(`calc${side}Level`).value),actual=record&&statsAtLevel(record.slice(3,9).map(Number),evs,ivs,null,level);return actual?[record[0],record[1],record[2],...actual.map((value,i)=>String(value-(i?20:75)-Number(evs[i]||0))),record[9]]:record},atk=replace(attacker,set.evs,'Atk'),def=replace(defender,defenderEvs,'Def'),adjusted={...master,pokemon:master.pokemon.map(row=>row[0]===attacker.name?atk:row[0]===defender.name?def:row)};return rawBattleCalculation(attacker,defender,set,move,defenderEvs,adjusted,options)}
