 function settings(){const a=row($('calcAtk').value.trim()),d=row($('calcDef').value.trim());if(!a||!d)return;const ar=sampleOf(a),dr=sampleOf(d),as=setOf(a),ds=setOf(d);$('calcAtkEvs').value=as.evs.join(',');$('calcDefEvs').value=ds.evs.join(',');syncStatEditors();options('calcAtkNature',ar.natures,as.natures,'무보정');options('calcDefNature',dr.natures,ds.natures,'무보정');options('calcAtkItem',ar.items,a.isMegaForm&&a.megaStone?a.megaStone:as.items,'도구 없음');options('calcDefItem',dr.items,d.isMegaForm&&d.megaStone?d.megaStone:ds.items,'도구 없음');options('calcAtkAbility',a.abilities?.length?a.abilities:ar.abilities,a.abilities?.[0]?.name||'','특성 미확인');options('calcDefAbility',d.abilities?.length?d.abilities:dr.abilities,d.abilities?.[0]?.name||'','특성 미확인');megaChoice('Atk',a);megaChoice('Def',d);summaries()}
 function summaries(){for(const [side,id] of [['Atk','calcAtk'],['Def','calcDef']]){const p=row($(id).value.trim()),base=p&&data.master.pokemon.find(x=>x[0]===p.name)?.slice(3,9).map(Number),stone=$(`calc${side}Mega`).value,mega=stone&&p?resolveCalculatorMegaForm(p,stone,data.master):null;$(`calc${side}Summary`).textContent=!base?'포켓몬을 선택하세요':mega?.ok?`${p.name} ${base.join('/')} → ${mega.formName} ${mega.formStats.join('/')} · ${mega.types.join('/')} · 특성 ${mega.ability||'미확인'}`:`${p.name} · ${base.join(' / ')}`}}
