 new MutationObserver(()=>{if(!$('calcResult').firstChild||$('calcResult').querySelector('[data-form-result]')||!lastForms)return;const note=document.createElement('p');note.dataset.formResult='';note.className='leadnotice';note.textContent=`폼 적용 — 공격: ${formText(lastForms.baseAttacker,lastForms.af)} / 수비: ${formText(lastForms.baseDefender,lastForms.df)}`;$('calcResult').append(note)}).observe($('calcResult'),{childList:true});
 function get(){const baseAttacker=row($('calcAtk').value.trim()),baseDefender=row($('calcDef').value.trim()),move=data.master.moves.find(m=>m[0]===$('calcMove').value);if(!baseAttacker||!baseDefender)return toast('현재 챔피언스 목록에서 공격·방어 포켓몬을 선택해 주세요.');if(!move)return toast('계산할 공격 기술을 선택해 주세요.');const af=chosenForm('Atk',baseAttacker),df=chosenForm('Def',baseDefender);if(!af||!df)return null;const attacker=af.pokemon,defender=df.pokemon,set={...setOf(baseAttacker),evs:ev('calcAtkEvs'),natures:$('calcAtkNature').value,items:af.form||baseAttacker.isMegaForm?'':$('calcAtkItem').value,abilities:af.form||baseAttacker.isMegaForm?'':$('calcAtkAbility').value},calc=battleCalculation(attacker,defender,set,move,ev('calcDefEvs'),formMaster(af,df),{defenderNature:$('calcDefNature').value,defenderHpPercent:$('calcHpPercent').value,hits:Number($('calcHits').value),attackerRank:Number($('calcAtkRank').value),defenderRank:Number($('calcDefRank').value),weather:$('calcWeather').value,field:$('calcField').value,wall:$('calcWall').value,critical:$('calcCritical').checked,charge:$('calcCharge').checked,helping:$('calcHelping').checked,battery:$('calcBattery').checked});if(!calc){toast('EV(각 0~32·합계 66), 현재 체력(1~100%), 타수(1~10)를 확인해 주세요.');return null}if(df.form?.ability==='부유'&&(koreanType[move[2]]||move[2])==='땅'){calc.typeMultiplier=0;calc.modifier=0;calc.damage=calc.damage.map(()=>0);calc.singleHitDamage=calc.singleHitDamage.map(()=>0);calc.result={label:'효과 없음',chance:0,min:0,max:0,minPct:0,maxPct:0}}lastForms={baseAttacker,baseDefender,af,df};return {attacker,defender,baseAttacker,baseDefender,attackerForm:af.form,defenderForm:df.form,move,set,calc}}
